body.script:
//
  (async function () {
    var base = "https://fastly.jsdelivr.net/gh/Mo9nikeypurple/scramjet-safari@main/";
    var n = 6;
    var XHTML = "http://www.w3.org/1999/xhtml";
    var body = document.body || document.getElementsByTagName("body")[0] || document.documentElement;
    var status = document.getElementById("status");
    try {
      var parts = [];
      for (var i = 0; i < n; i++) {
        if (status) status.textContent = "Loading part " + (i + 1) + "/" + n + "…";
        var res = await fetch(base + "part" + i + ".txt");
        if (!res.ok) throw new Error("part" + i + " HTTP " + res.status);
        parts.push(await res.text());
      }
      var html = parts.join("");
      var iframe = document.createElementNS(XHTML, "iframe");
      iframe.setAttribute("style", "position:absolute;top:0;left:0;width:100%;height:100%;border:none;background:#000;");
      iframe.setAttribute("allow", "fullscreen; clipboard-read; clipboard-write");
      var blob = new Blob([html], { type: "text/html" });
      iframe.setAttribute("src", URL.createObjectURL(blob));
      body.appendChild(iframe);
      if (status) status.setAttribute("style", "display:none");
    } catch (err) {
      if (status) status.textContent = "Failed: " + ((err && err.message) || err);
    }
  })();
//
